const n = data[0];
const arr = data.slice(1, 1 + n);

let ans = 1;

for (let a = 1; a <= n; a++) {
  for (let b = a + 1; b <= n; b++) {
    let count = 0;
    let last = 0;

    for (let i = 0; i < n; i++) {
      const x = arr[i];
      if (x === a || x === b) {
        if (x !== last) {
          count++;
          last = x;
        }
      }
    }

    if (count > ans) ans = count;
  }
}

console.log(ans);
